html:pre.html:code:
// Entrées: Deux entiers x et y positifs
// Sortie: La somme des deux entrées
int somme (int x , int y){
  if (y <= 0){
    return x;
  }
  else {
    return somme(x,y-1)+1;
  }   
}

// Entrée: un entier n
// Sortie: la somme des carrés de 1 à n
int sommecarres (int n){
  if (n <= 0){
    return 0;
  }
  else {
    return sommecarres(n-1)+(n*n);
  }   
}

// Entrées: Un entier x positif ou nul
// Sortie: L'entier x incrémenté de 1
#include <iostream>
using namespace std;

int incrementer (int x){
    if (x == 0){
        return 1;
    }
    else{
        return incrementer (x-1) + 1;
    }
    return 0;
}

